import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import app.morphe.patcher.patch.PatchKt;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonParser;

class ExportPatchMetadata {
    public static void main(String[] args) throws Exception {
        var patches = PatchKt.loadPatchesFromJar(Set.of(new File(args[0])));
        // The pinned library's CLI picks an arbitrary .mpp from build/libs; its exporter accepts explicit inputs.
        var generator = Class.forName("app.morphe.util.PatchListGeneratorKt")
                .getDeclaredMethod("generatePatchList", String.class, Set.class);
        generator.setAccessible(true);
        generator.invoke(null, args[1], patches);
        var path = Path.of("../patches-list.json");
        var json = JsonParser.parseString(Files.readString(path)).getAsJsonObject();
        json.addProperty("NOTE", "Generated by .github/scripts/prepare_release.py. Do not edit manually.");
        for (var entry : json.getAsJsonArray("patches")) {
            var object = entry.getAsJsonObject();
            var name = object.get("name").getAsString();
            var patch = patches.stream().filter(p -> name.equals(p.getName())).findFirst().orElseThrow();
            var dependencies = new JsonArray();
            for (var dependency : patch.getDependencies()) {
                dependencies.add(dependency.getName() == null
                        ? dependency.getClass().getSimpleName() : dependency.getName());
            }
            object.remove("dependencies");
            object.add("dependencies", dependencies);
        }
        Files.writeString(path, new GsonBuilder().setPrettyPrinting().serializeNulls()
                .disableHtmlEscaping().create().toJson(json) + "\n");
    }
}
